// pending 인 주문에 결제 번호를 적고 confirming 으로 바꾼다. 결제 대행사를 부르기 전에 한다.
// 만료 시각이 지난 주문은 바꾸지 않는다. 정리 작업이 아직 expired 로 바꾸지 않았어도 치를 수 없다.
func (q *Queries) StartConfirming(ctx context.Context, arg StartConfirmingParams) (Order, error) {
	row := q.db.QueryRow(ctx, startConfirming,
		arg.PaymentKey,
		arg.Now,
		arg.ID,
		arg.UserID,
	)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.ProductID,
		&i.Price,
		&i.Credits,
		&i.Status,
		&i.IdempotencyKey,
		&i.PaymentKey,
		&i.FailureCode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PaidAt,
		&i.ExpiresAt,
		&i.RefundedAt,
		&i.Channel,
	)
	return i, err
}

const startRefunding = `-- name: StartRefunding :one
UPDATE orders
SET status = 'refunding', updated_at = $1::TIMESTAMPTZ
WHERE id = $2 AND user_id = $3 AND status = 'paid'
    AND paid_at > $4::TIMESTAMPTZ
RETURNING id, user_id, product_id, price, credits, status, idempotency_key, payment_key, failure_code, created_at, updated_at, paid_at, expires_at, refunded_at, channel
`

type StartRefundingParams struct {
	Now       time.Time
	ID        uuid.UUID
	UserID    uuid.UUID
	PaidAfter time.Time
}

// paid 인 주문을 refunding 으로 바꾼다. 치른 시각이 paid_after 보다 늦은 것(청약철회 기한 안)만 바꾼다.
// 그 주문의 묶음을 비우는 일과 같은 트랜잭션에서 한다. 결제 대행사를 부르기 전에 한다.
func (q *Queries) StartRefunding(ctx context.Context, arg StartRefundingParams) (Order, error) {
	row := q.db.QueryRow(ctx, startRefunding,
		arg.Now,
		arg.ID,
		arg.UserID,
		arg.PaidAfter,
	)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.ProductID,
		&i.Price,
		&i.Credits,
		&i.Status,
		&i.IdempotencyKey,
		&i.PaymentKey,
		&i.FailureCode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PaidAt,
		&i.ExpiresAt,
		&i.RefundedAt,
		&i.Channel,
	)
	return i, err
}
